// about the Vector3 axis; push; return 1.
let axis = check_vector3_slot(thread, 1);
let angle = lua_to_number_or_zero(thread, 2) as f32;
let len = (axis.x * axis.x + axis.y * axis.y + axis.z * axis.z).sqrt();
let inv = 1.0 / len;
