let (s, c) = angle.sin_cos();
let t = 1.0 - c;
let rotation = [[t * x * x + c, t * x * y - s * z, t * x * z + s * y], [t * x * y + s * z, t * y * y + c, t * y * z - s * x], [t * x * z - s * y, t * y * z + s * x, t * z * z + c]];
let frame = LuaCoordinateFrame { position: LuaVector3 { x: 0.0, y: 0.0, z: 0.0 }, rotation };
push_new_object(thread, lua_bridge_class::CFRAME, LuaUserdataPayload::CoordinateFrame(frame));
