#[doc(alias = "lua_gettable(lua_State *,int)")]
pub fn stub_0x82317c(thread: &mut LuaThreadState, index: usize) {
// lua_gettable — named lookup of the key on top; missing
// keys push nil.
let key = thread.stack.pop().unwrap_or(LuaStackValue::Nil);
let found = match (thread.slot(index), &key) {
    (Some(LuaStackValue::Table(t)), LuaStackValue::String(k)) => t.named.iter().find(|(ek, _)| matches!(ek, LuaTableKey::Str(s) if s == k)).map(|(_, v)| v.clone()),
    _ => None,
};
thread.push(found.unwrap_or(LuaStackValue::Nil));
}

