/// `luaL_checkudata(L, index, CoordinateFrame)` host check behind the
/// CoordinateFrame bridge arithmetic: a missing slot or a wrong-typed slot
/// throws, like the C++ `luaL_checkudata` error (cf. 0x273c5a).
pub(crate) fn check_coordinateframe_slot(thread: &LuaThreadState, index: usize) -> LuaCoordinateFrame {
    match thread.slot(index) {
        Some(LuaStackValue::Userdata(ud)) if ud.class == lua_bridge_class::CFRAME => match &ud.payload {
            LuaUserdataPayload::CoordinateFrame(v) => *v,
            _ => panic!("CoordinateFrame expected"),
        },
        _ => panic!("CoordinateFrame expected"),
    }
}

